143	    Pos((usize, usize)),
144	
145	    /// Parsing a optional flag argument
146	    Opt((&'a clap::Arg, usize)),
147	}
148	
149	fn complete_arg(
150	    arg: &clap_lex::ParsedArg<'_>,
151	    cmd: &clap::Command,
152	    current_dir: Option<&std::path::Path>,
153	    pos_index: usize,
154	    is_escaped: bool,
155	    state: ParseState<'_>,
156	    used_args: &[clap::Id],
157	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
158	    debug!(
159	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
160	        arg,
161	        cmd.get_name(),
162	        current_dir,
163	        pos_index,
164	        state
165	    );
166	    let mut completions = Vec::<CompletionCandidate>::new();
167	
168	    match state {
169	        ParseState::ValueDone => {
170	            if !is_escaped {
171	                if let Ok(value) = arg.to_value() {
172	                    completions.extend(complete_subcommand(value, cmd));
173	                }
174	            }
175	
176	            if let Some(positional) = cmd
177	                .get_positionals()
178	                .find(|p| p.get_index() == Some(pos_index))
179	            {
180	                completions.extend(complete_arg_value(
181	                    arg.to_value(),
182	                    positional,
183	                    current_dir,
184	                    0,
185	                ));
186	            }
187	            if !is_escaped {
188	                completions.extend(complete_option(arg, cmd, current_dir));
189	            }
190	        }
191	        ParseState::Pos((_, num_arg)) => {
192	            if let Some(positional) = cmd
193	                .get_positionals()
194	                .find(|p| p.get_index() == Some(pos_index))
195	            {
196	                completions.extend(complete_arg_value(
197	                    arg.to_value(),
198	                    positional,
199	                    current_dir,
200	                    num_arg.saturating_sub(1),
201	                ));
202	                if !is_escaped
203	                    && positional
204	                        .get_num_args()
205	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
206	                {
207	                    completions.extend(complete_option(arg, cmd, current_dir));
208	                }
209	            }
210	        }
211	        ParseState::Opt((opt, count)) => {
212	            completions.extend(complete_arg_value(
213	                arg.to_value(),
214	                opt,
215	                current_dir,
216	                count.saturating_sub(1),
217	            ));
218	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
219	            if count > min && can_switch_to_other_arg(opt, arg) {
220	                // The option's required values are satisfied and this word
221	                // would be parsed as a new flag rather than another value, so
222	                // also complete it as a positional, flag, option or subcommand.
223	                completions.extend(complete_arg(
224	                    arg,
225	                    cmd,
226	                    current_dir,
227	                    pos_index,
228	                    is_escaped,
229	                    ParseState::ValueDone,
230	                    used_args,
231	                )?);
232	            }
233	        }
234	    }
235	    filter_conflicting_candidates(&mut completions, cmd, used_args);
236	    if completions.iter().any(|a| !a.is_hide_set()) {
237	        completions.retain(|a| !a.is_hide_set());
238	    }
239	    let mut seen_ids = std::collections::HashSet::new();
240	    completions.retain(move |a| {
241	        if let Some(id) = a.get_id().cloned() {
242	            seen_ids.insert(id)
243	        } else {
244	            true
245	        }
246	    });
247	
248	    let mut tags = Vec::new();
249	    for candidate in &completions {
250	        let tag = candidate.get_tag().cloned();
251	        if !tags.contains(&tag) {
252	            tags.push(tag);
253	        }
254	    }
255	    completions.sort_by_key(|c| {
256	        (
257	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
258	            c.get_display_order(),
259	        )
260	    });
261	
262	    Ok(completions)
263	}
264	
265	fn complete_option(
266	    arg: &clap_lex::ParsedArg<'_>,
267	    cmd: &clap::Command,
268	    current_dir: Option<&std::path::Path>,
269	) -> Vec<CompletionCandidate> {
270	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
271	    let mut completions = Vec::<CompletionCandidate>::new();
272	    if arg.is_empty() {
273	        completions.extend(longs_and_visible_aliases(cmd));
274	        completions.extend(hidden_longs_aliases(cmd));
275	
276	        let dash_or_arg = if arg.is_empty() {
277	            "-".into()
278	        } else {
279	            arg.to_value_os().to_string_lossy()
280	        };
281	        completions.extend(
282	            shorts_and_visible_aliases(cmd)
283	                .into_iter()
284	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
285	        );
286	    } else if arg.is_stdio() {
287	        // HACK: Assuming knowledge of is_stdio
288	        let dash_or_arg = if arg.is_empty() {
289	            "-".into()
290	        } else {
291	            arg.to_value_os().to_string_lossy()
292	        };
293	        completions.extend(
294	            shorts_and_visible_aliases(cmd)
295	                .into_iter()
296	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
297	        );
298	
299	        completions.extend(longs_and_visible_aliases(cmd));
300	        completions.extend(hidden_longs_aliases(cmd));
301	    } else if arg.is_escape() {
302	        // HACK: Assuming knowledge of is_escape
303	        completions.extend(longs_and_visible_aliases(cmd));
304	        completions.extend(hidden_longs_aliases(cmd));
305	    } else if let Some((flag, value)) = arg.to_long() {
306	        if let Ok(flag) = flag {
307	            if let Some(value) = value {
308	                if let Some(arg) = cmd.get_arguments().find(|a| is_long_match(a, flag)) {
309	                    completions.extend(
310	                        complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
311	                            .into_iter()
312	                            .map(|comp| comp.add_prefix(format!("--{flag}="))),
313	                    );
314	                }
315	            } else {
316	                completions.extend(
317	                    longs_and_visible_aliases(cmd)
318	                        .into_iter()
319	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
320	                );
321	                completions.extend(
322	                    hidden_longs_aliases(cmd)
323	                        .into_iter()
324	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
325	                );
326	            }
327	        }
328	    } else if let Some(short) = arg.to_short() {
329	        if !short.is_negative_number() {
330	            // Find the first takes_values option.
331	            let (leading_flags, _, takes_value_opt, mut short) = parse_shortflags(cmd, short);
332	
333	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
334	            if let Some(opt) = takes_value_opt {
335	                let mut peek_short = short.clone();
336	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
337	                    short.next_flag();
338	                    true
339	                } else {
340	                    false
341	                };
342	
343	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
344	                completions.extend(
345	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
346	                        .into_iter()
347	                        .map(|comp| {
348	                            let sep = if has_equal { "=" } else { "" };
349	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
350	                        }),
351	                );
352	            } else {
353	                completions.extend(
354	                    shorts_and_visible_aliases(cmd)
355	                        .into_iter()
356	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
357	                );
358	            }
359	        }
360	    }
361	    debug!("complete_option: completions={completions:?}");
362	    completions
363	}
364	
365	fn complete_arg_value(
366	    value: Result<&str, &OsStr>,
367	    arg: &clap::Arg,
368	    current_dir: Option<&std::path::Path>,
369	    arg_index: usize,
370	) -> Vec<CompletionCandidate> {
371	    let mut values = Vec::new();
372	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
373	
374	    let (prefix, value) =
375	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
376	
377	    let value_os = match value {
378	        Ok(value) => OsStr::new(value),
379	        Err(value_os) => value_os,
380	    };
381	
382	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
383	        values.extend(completer.complete_at(arg_index, value_os));
384	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
385	        values.extend(complete_value_candidates(
386	            value_os,
387	            completer.value_candidates(),
388	        ));
389	    } else if let Some(possible_values) = possible_values(arg) {
390	        if let Ok(value) = value {
391	            values.extend(complete_candidates_str(
392	                value,
393	                possible_value_candidates(possible_values),
394	            ));
395	        }
396	    } else {
397	        match arg.get_value_hint() {
398	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
399	                // Should not complete
400	            }
401	            clap::ValueHint::AnyPath => {
402	                values.extend(complete_path(value_os, current_dir, &|_| true));
403	            }
404	            clap::ValueHint::FilePath => {
405	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
406	            }
407	            clap::ValueHint::DirPath => {
408	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
409	            }
410	            clap::ValueHint::ExecutablePath => {
411	                use is_executable::IsExecutable;
412	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
413	            }
414	            clap::ValueHint::CommandName
415	            | clap::ValueHint::CommandString
416	            | clap::ValueHint::CommandWithArguments
417	            | clap::ValueHint::Username
418	            | clap::ValueHint::Hostname
419	            | clap::ValueHint::Url
420	            | clap::ValueHint::EmailAddress => {
421	                // No completion implementation
422	            }
423	            _ => {
424	                // Safe-ish fallback
425	                values.extend(complete_path(value_os, current_dir, &|_| true));
426	            }
427	        }
428	
429	        values.sort();
430	    }
431	
432	    if let Some(prefix) = prefix {
433	        values = values
434	            .into_iter()
435	            .map(|comp| comp.add_prefix(prefix))
436	            .collect();
437	    }
438	    values = values
439	        .into_iter()
440	        .map(|comp| {
441	            if comp.get_tag().is_some() {
442	                comp
443	            } else {
444	                comp.tag(Some(arg.to_string().into()))
445	            }
446	        })
447	        .collect();
448	
449	    debug!("complete_arg_value: values={values:?}");
450	    values
451	}
452	
453	fn rsplit_delimiter<'s, 'o>(
454	    value: Result<&'s str, &'o OsStr>,
455	    delimiter: Option<char>,
456	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
457	    let delimiter = delimiter?;
458	    let value = value.ok()?;
459	    let pos = value.rfind(delimiter)?;
460	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
461	    Some((Some(prefix), Ok(value)))
462	}
