475	fn complete_candidates_str(
476	    value: &str,
477	    mut values: Vec<CompletionCandidate>,
478	) -> Vec<CompletionCandidate> {
479	    debug!("complete_candidates_str: value={value:?}");
480	
481	    values.retain(|comp| comp.get_value().starts_with(value));
482	    values
483	}
