485	fn complete_value_candidates_str(
486	    value: &str,
487	    completer: &dyn ValueCandidates,
488	) -> Vec<CompletionCandidate> {
489	    debug!("complete_value_candidates_str: value={value:?}");
490	
491	    complete_candidates_str(value, completer.candidates())
492	}
