609	                .into_iter()
610	                .map(|s| populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc))
611	                .chain(sc.get_aliases().map(|s| {
612	                    populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc)
613	                        .hide(true)
614	                }))
615	        })
616	        .collect()
617	}
