740	/// Parse the positional arguments. Return the new state and the new positional index.
741	fn parse_positional<'a>(
742	    cmd: &clap::Command,
743	    pos_index: usize,
744	    is_escaped: bool,
745	    state: ParseState<'a>,
746	) -> (ParseState<'a>, usize) {
747	    let pos_arg = cmd
748	        .get_positionals()
749	        .find(|p| p.get_index() == Some(pos_index));
750	    let num_args = pos_arg
751	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
752	        .unwrap_or(1);
753	
754	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
755	        if num_args > 1 {
756	            (ParseState::Pos((pos_index, 1)), pos_index)
757	        } else {
758	            if is_escaped {
759	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
760	            } else {
761	                (ParseState::ValueDone, pos_index + 1)
762	            }
763	        }
764	    };
765	    match state {
766	        ParseState::ValueDone => {
767	            update_state_with_new_positional(pos_index)
768	        },
769	        ParseState::Pos((prev_pos_index, num_arg)) => {
770	            if prev_pos_index == pos_index {
771	                if num_arg + 1 < num_args {
772	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
773	                } else {
774	                    if is_escaped {
775	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
776	                    } else {
777	                        (ParseState::ValueDone, pos_index + 1)
778	                    }
779	                }
780	            } else {
781	                update_state_with_new_positional(pos_index)
782	            }
783	        }
784	        ParseState::Opt(..) => unreachable!(
785	            "This branch won't be hit,
786	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
787	        ),
788	    }
789	}
790	
791	/// Parse optional flag argument. Return new state
792	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
793	    let range = opt.get_num_args().expect("built");
794	    let max = range.max_values();
795	    if count < max {
796	        ParseState::Opt((opt, count + 1))
797	    } else {
798	        ParseState::ValueDone
799	    }
800	}
801	
802	/// How many of an option's values an attached `=value` (or `-ovalue`) accounts
803	/// for, honoring the value delimiter.
804	fn attached_value_count(opt: &clap::Arg, value: &OsStr) -> usize {
805	    match (opt.get_value_delimiter(), value.to_str()) {
806	        (Some(delimiter), Some(value)) => value.split(delimiter).count(),
807	        _ => 1,
808	    }
809	}
810	
811	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
812	    cmd.get_positionals()
813	        .find(|a| a.get_index() == Some(pos_index))
814	        .map(|p| p.is_allow_hyphen_values_set())
815	        .unwrap_or(false)
816	}
817	
818	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
819	    let val = arg.to_value_os();
820	    if val.starts_with("-") {
821	        if let ParseState::Opt((opt, _)) = state {
822	            return opt.is_allow_hyphen_values_set();
823	        }
824	    }
825	
826	    false
827	}
828	
829	/// Whether a word can terminate a still-open multi-value option and start a
830	/// new argument instead, the way the parser would read it.
831	///
832	/// While an option still owes values, the parser greedily consumes every plain
833	/// word as one of its values; only flag-like words can switch to another
834	/// argument. An option that accepts hyphen values consumes those too.
835	fn can_switch_to_other_arg(pending: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
836	    if arg.is_escape() {
837	        // `--` cancels every pending option unless its values may start with `--`.
838	        return !pending.is_allow_hyphen_values_set();
839	    }
840	    if !arg.to_value_os().starts_with("-") {
841	        // A plain word is always another value of the pending option.
842	        return false;
843	    }
844	    if pending.is_allow_hyphen_values_set() {
845	        return false;
846	    }
847	    // `-` is a stdio/value, not a flag.
848	    if arg.is_stdio() {
849	        return false;
850	    }
851	    // Both long and short flag styles can start a new argument; unknown flags
852	    // still switch (and error during parsing) rather than become option values.
853	    arg.to_long().is_some() || arg.to_short().is_some()
854	}
