408	fn split_file_name(path: &std::path::Path) -> (&std::path::Path, &OsStr) {
409	    // Workaround that `Path::new("name/").file_name()` reports `"name"`
410	    if path_has_name(path) {
411	        (
412	            path.parent().unwrap_or_else(|| std::path::Path::new("")),
413	            path.file_name().expect("not called with `..`"),
414	        )
415	    } else {
416	        (path, Default::default())
417	    }
418	}
