420	fn path_has_name(path: &std::path::Path) -> bool {
421	    let path_bytes = path.as_os_str().as_encoded_bytes();
422	    let Some(trailing) = path_bytes.last() else {
423	        return false;
424	    };
425	    let trailing = *trailing as char;
