    );
    assert_eq!(
        optional_value_tool_values(&["tool", "--color=always", "--", ""]),
        ["src-a", "src-b"]
    );
    assert_eq!(
        optional_value_tool_values(&["tool", "--color", "--", "s"]),
        ["src-a", "src-b"]
    );
    // Later words keep filling the current level's positionals.
    assert_eq!(
        optional_value_tool_values(&["tool", "--color", "--", "src-a", ""]),
